package com.game_manager.gm.document;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.sql.Timestamp; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.http.MediaType; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.mock.web.MockMultipartFile; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.*; import tools.jackson.databind.ObjectMapper;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class DocumentSecurityIntegrationTest {
 @Autowired MockMvc mvc; @Autowired JdbcTemplate db; @Autowired PasswordEncoder encoder; @Autowired DocumentVersionRepository versions; private final ObjectMapper json=new ObjectMapper();
 @Test void quarantinePrivateAuthorizationMimeAndDownloadHeaders()throws Exception{UUID first=user(),second=user();String one=login(first),two=login(second);MockMultipartFile text=new MockMultipartFile("file","../../private.txt","text/plain","private content".getBytes());MvcResult created=mvc.perform(multipart("/api/v1/documents").file(text).param("resourceType","GENERAL").param("resourceId",first.toString()).header("Authorization",bearer(one))).andExpect(status().isCreated()).andExpect(jsonPath("$.versions[0].filename").value("private.txt")).andExpect(jsonPath("$.versions[0].scanStatus").value("PENDING")).andReturn();UUID documentId=UUID.fromString(json.readTree(created.getResponse().getContentAsByteArray()).get("id").asText());mvc.perform(get("/api/v1/documents/{id}/content",documentId).header("Authorization",bearer(one))).andExpect(status().isLocked());mvc.perform(get("/api/v1/documents/{id}/content",documentId).header("Authorization",bearer(two))).andExpect(status().isNotFound());mvc.perform(get("/api/v1/documents").param("resourceType","GENERAL").param("resourceId",first.toString()).header("Authorization",bearer(two))).andExpect(status().isNotFound());DocumentVersion version=versions.findAll().stream().filter(v->v.getDocument().getId().equals(documentId)).findFirst().orElseThrow();version.setScanStatus(ScanStatus.CLEAN);version.setScannedAt(Instant.now());versions.saveAndFlush(version);mvc.perform(get("/api/v1/documents/{id}/content",documentId).header("Authorization",bearer(one))).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Cache-Control","private, no-store")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.containsString("attachment"))).andExpect(content().bytes("private content".getBytes()));MockMultipartFile fake=new MockMultipartFile("file","fake.pdf","application/pdf","not a pdf".getBytes());mvc.perform(multipart("/api/v1/documents").file(fake).param("resourceType","GENERAL").param("resourceId",first.toString()).header("Authorization",bearer(one))).andExpect(status().isBadRequest());}
 private UUID user(){UUID id=UUID.randomUUID();Instant now=Instant.now();db.update("INSERT INTO users(id,name,email,password_hash,role,active,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?,0)",id.toString(),"Document User",id+"@example.com",encoder.encode("StrongPass1!"),"CUSTOMER",true,Timestamp.from(now),Timestamp.from(now));return id;}private String login(UUID id)throws Exception{String email=db.queryForObject("SELECT email FROM users WHERE id=?",String.class,id.toString());MvcResult result=mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"StrongPass1!\"}")).andExpect(status().isOk()).andReturn();return json.readTree(result.getResponse().getContentAsByteArray()).get("token").asText();}private static String bearer(String token){return "Bearer "+token;}
}
